187	                      message: messages[index],
188	                    ),
189	                  ),
190	                },
191	              ),
192	            ),
193	            _ChatComposer(
194	              controller: _textController,
195	              focusNode: _composerFocusNode,
196	              onSend: _send,
197	            ),
198	          ],
199	        ),
200	      ),
201	    );
202	  }
