import 'support/fake_connectivity_watcher.dart';

const _session = ChatSession(
  id: 's1',
  title: '',
  persona: ChatPersona.analitico,
  userMessageCount: 0,
  lastUserMessageAt: null,
  createdAt: '2026-01-01T00:00:00Z',
  updatedAt: '2026-01-01T00:00:00Z',
);

class _FakeChatRepository implements ChatRepository {
  @override
  Future<Either<Failure, List<ChatSession>>> listSessions() async =>
      right([_session]);
  @override
  Future<Either<Failure, ChatSession>> createSession() async =>
      right(_session);
  @override
  Future<Either<Failure, List<ChatMessage>>> listMessages(
    String sessionId,
  ) async => right(const []);
  @override
  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
    String sessionId,
    String content,
  ) => const Stream.empty();
  @override
  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
    String sessionId,
    String userMessageId,
  ) => const Stream.empty();
}

void main() {
  testWidgets('debug drawer offline', (tester) async {
    final repo = _FakeChatRepository();
    final watcher = FakeConnectivityWatcher();
    final cubit = ChatCubit(repo, watcher);
    await cubit.init();

    await tester.pumpWidget(
      MaterialApp(
        home: BlocProvider<ChatCubit>.value(
          value: cubit,
          child: Scaffold(
            drawer: Drawer(
              child: BlocBuilder<ChatCubit, ChatState>(
                builder: (context, state) {
                  final isOffline = state is ChatReady && state.isOffline;
                  // ignore: avoid_print
                  print('DEBUG builder called isOffline=$isOffline');
                  return Text('isOffline=$isOffline');
                },
              ),
            ),
            body: const SizedBox.shrink(),
          ),
        ),
      ),
    );

    tester.state<ScaffoldState>(find.byType(Scaffold)).openDrawer();
    await tester.pumpAndSettle();

    expect(find.text('isOffline=false'), findsOneWidget);

    watcher.emit(false);
    await tester.pumpAndSettle();

    expect(find.text('isOffline=true'), findsOneWidget);
  });
}

